import { Component, OnInit, OnDestroy } from '@angular/core';
import { TaskService } from '../services/task-services';
import { AuthService } from '../services/auth.service';

interface TaskItem {
  id: string;
  title: string;
  category: string;
  priority: string;
  status: string;
  estimated_time: number;
  due_date: string;
  created_at: string;
  // UI state
  _loading?: boolean;
  _elapsed?: number;
  _timerRef?: any;
}

@Component({
  selector: 'app-task',
  templateUrl: './task.html',
  styleUrls: ['./task.css']
})
export class TaskComponent implements OnInit, OnDestroy {

  tasks: TaskItem[] = [];
  pageLoading = true;

  // Modal state
  modalOpen = false;
  modalTask: TaskItem | null = null;
  focusScore = 3;
  distractionCount = 0;
  modalLoading = false;
  modalError = '';

  // Toast
  toast: { type: 'success' | 'error'; message: string } | null = null;
  private toastTimer: any;

  // Filter
  filter: 'All' | 'Pending' | 'In Progress' | 'Completed' = 'All';

  constructor(private taskService: TaskService, private auth: AuthService) {}

  ngOnInit() { this.loadTasks(); }

  ngOnDestroy() {
    this.tasks.forEach(t => { if (t._timerRef) clearInterval(t._timerRef); });
  }

  get userId(): string { return this.auth.getUser()?.id ?? ''; }

  get filteredTasks(): TaskItem[] {
    return this.filter === 'All' ? this.tasks : this.tasks.filter(t => t.status === this.filter);
  }

  get counts() {
    return {
      all: this.tasks.length,
      pending: this.tasks.filter(t => t.status === 'Pending').length,
      inProgress: this.tasks.filter(t => t.status === 'In Progress').length,
      completed: this.tasks.filter(t => t.status === 'Completed').length,
    };
  }

  loadTasks() {
    this.pageLoading = true;
    this.taskService.getTasks().subscribe({
      next: (data) => {
        this.tasks = (data as TaskItem[]).map(t => ({ ...t, _loading: false, _elapsed: 0 }));
        this.pageLoading = false;
      },
      error: () => {
        this.pageLoading = false;
        this.showToast('error', '❌ Failed to load tasks');
      }
    });
  }

  startTask(task: TaskItem) {
    task._loading = true;
    this.taskService.startTask(task.id, this.userId).subscribe({
      next: () => {
        task.status = 'In Progress';
        task._loading = false;
        task._elapsed = 0;
        task._timerRef = setInterval(() => task._elapsed = (task._elapsed ?? 0) + 1, 1000);
        this.showToast('success', `▶️ "${task.title}" started`);
      },
      error: (err) => {
        task._loading = false;
        this.showToast('error', '❌ ' + (err?.error?.detail ?? 'Failed to start task'));
      }
    });
  }

  openModal(task: TaskItem) {
    this.modalTask = task;
    this.focusScore = 3;
    this.distractionCount = 0;
    this.modalError = '';
    this.modalOpen = true;
  }

  closeModal() {
    this.modalOpen = false;
    this.modalTask = null;
    this.modalLoading = false;
    this.modalError = '';
  }

  submitComplete() {
    if (!this.modalTask) return;
    if (this.distractionCount < 0) { this.modalError = 'Distraction count cannot be negative.'; return; }

    this.modalLoading = true;
    this.modalError = '';

    const payload = {
      focus_score: this.focusScore,
      distraction_count: this.distractionCount,
      user_id: this.userId
    };

    this.taskService.completeTask(this.modalTask.id, payload).subscribe({
      next: () => {
        const t = this.tasks.find(x => x.id === this.modalTask!.id);
        if (t) {
          t.status = 'Completed';
          if (t._timerRef) { clearInterval(t._timerRef); t._timerRef = null; }
        }
        this.showToast('success', `✅ "${this.modalTask!.title}" completed!`);
        this.closeModal();
      },
      error: (err) => {
        this.modalLoading = false;
        this.modalError = err?.error?.detail ?? 'Failed to complete task.';
      }
    });
  }

  formatElapsed(secs: number = 0): string {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  }

  priorityClass(p: string) {
    return p === 'High' ? 'p-high' : p === 'Medium' ? 'p-med' : 'p-low';
  }

  statusClass(s: string) {
    return s === 'Completed' ? 's-done' : s === 'In Progress' ? 's-progress' : 's-pending';
  }

  private showToast(type: 'success' | 'error', message: string) {
    clearTimeout(this.toastTimer);
    this.toast = { type, message };
    this.toastTimer = setTimeout(() => this.toast = null, 4000);
  }
}
