import { Component, OnInit, AfterViewInit, ElementRef, ViewChild } from '@angular/core';

declare const Chart: any;

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.html',
  styleUrls: ['./dashboard.css']
})
export class DashboardComponent implements OnInit, AfterViewInit {

  @ViewChild('lineChart') lineChartRef!: ElementRef<HTMLCanvasElement>;
  @ViewChild('pieChart') pieChartRef!: ElementRef<HTMLCanvasElement>;

  score = 78;
  today = new Date();
  circumference = 2 * Math.PI * 36;
  get dashOffset() { return this.circumference * (1 - this.score / 100); }

  stats = [
    { icon: '✅', label: 'Tasks Completed Today', value: 8, color: '#10b981' },
    { icon: '⏳', label: 'Tasks Pending', value: 5, color: '#f59e0b' },
    { icon: '🕐', label: 'Time Spent Today', value: '6.5h', color: '#6366f1' },
  ];

  insights = [
    { icon: '⚡', text: 'You are most productive between 10 AM – 12 PM', color: '#f59e0b' },
    { icon: '📅', text: 'You complete more tasks on weekdays', color: '#10b981' },
    { icon: '⚠️', text: 'High priority tasks take longer than expected', color: '#ef4444' },
    { icon: '🔁', text: 'You tend to reschedule tasks after 4 PM', color: '#6366f1' },
    { icon: '🎯', text: 'Focus sessions under 90 min yield best results', color: '#f59e0b' },
  ];

  recommendations = [
    { icon: '🧠', text: 'Recommended: Do high-focus tasks now (peak hours)' },
    { icon: '🚫', text: 'Avoid adding more than 5 tasks today' },
    { icon: '🔥', text: 'You are already at 78% capacity — pace yourself' },
  ];

  tasks = [
    { title: 'Finalize project report', priority: 'High', time: '2h', status: 'Pending', ai: '⚠️ May take longer than usual' },
    { title: 'Review pull requests', priority: 'Medium', time: '45m', status: 'Completed', ai: null },
    { title: 'Team standup meeting', priority: 'Low', time: '30m', status: 'Completed', ai: null },
    { title: 'Update API documentation', priority: 'High', time: '1.5h', status: 'Pending', ai: '💡 Best done in morning hours' },
    { title: 'Exercise / workout', priority: 'Medium', time: '1h', status: 'Pending', ai: null },
    { title: 'Read research paper', priority: 'Low', time: '1h', status: 'Pending', ai: '⚠️ Often skipped — schedule it early' },
  ];

  heatmapCells: { level: number; date: string }[] = [];

  ngOnInit() {
    this.buildHeatmap();
  }

  ngAfterViewInit() {
    this.initLineChart();
    this.initPieChart();
  }

  buildHeatmap() {
    const today = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const label = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      this.heatmapCells.push({ level: Math.floor(Math.random() * 5), date: label });
    }
  }

  initLineChart() {
    const labels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const data = [4, 7, 5, 9, 6, 3, 8];
    new Chart(this.lineChartRef.nativeElement, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Tasks Completed',
          data,
          borderColor: '#f59e0b',
          backgroundColor: 'rgba(245,158,11,0.08)',
          pointBackgroundColor: '#f59e0b',
          pointRadius: 5,
          pointHoverRadius: 7,
          tension: 0.4,
          fill: true,
          borderWidth: 2.5,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 900, easing: 'easeInOutQuart' },
        plugins: { legend: { display: false } },
        scales: {
          x: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { family: 'Inter', size: 12 } } },
          y: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { family: 'Inter', size: 12 }, stepSize: 2 }, beginAtZero: true }
        }
      }
    });
  }

  initPieChart() {
    new Chart(this.pieChartRef.nativeElement, {
      type: 'doughnut',
      data: {
        labels: ['Work', 'Study', 'Health', 'Personal'],
        datasets: [{
          data: [40, 25, 20, 15],
          backgroundColor: ['#f59e0b', '#6366f1', '#10b981', '#ec4899'],
          borderColor: '#111111',
          borderWidth: 3,
          hoverOffset: 8,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 900, easing: 'easeInOutQuart' },
        plugins: {
          legend: {
            position: 'bottom',
            labels: { color: '#9ca3af', font: { family: 'Inter', size: 12 }, padding: 16, boxWidth: 12, borderRadius: 4 }
          }
        },
        cutout: '65%',
      }
    });
  }

  priorityClass(p: string) {
    return p === 'High' ? 'badge-high' : p === 'Medium' ? 'badge-med' : 'badge-low';
  }
}
